function agentBindAssetGrid(scope,assets){if(!scope||!Array.isArray(assets)||!assets.length)return;const urls=assets.map(a=>a.url);const caps=assets.map(a=>a.label||"素材图");[...scope.querySelectorAll(".agent-lv-box")].forEach((box,i)=>{box.addEventListener("click",()=>openLightbox(urls,i,caps[i]));});}
function agentRenderMsg(msg){if(!msg)return;if(msg.type==="user"){const el=agentAddMsg("user",msg.text||"",msg.time);agentRenderBubbleAssets(el,msg.assets);return;}
if(!msg.videoId&&!msg.taskId){const el=agentAddMsg("bot","",msg.time);const bb=el.querySelector(".bubble");let html=agentThinkHtml(msg.think||"",msg.thinkMs);if(msg.text)html+=`<div class="agent-text">${agentFmt(msg.text)}</div>`;if(msg.backend&&msg.model){const beLabel=msg.backend==="ms"?"魔搭":"Agnes";html+=`<div class="agent-backend-tag" style="margin-top:8px;font-size:11px;color:var(--sub);opacity:.75">${esc(beLabel)} · ${esc(msg.model)}</div>`;}
if(msg.status==="stopped")html+='<div class="agent-stopped">已停止生成</div>';if(msg.error&&!msg.text){html+=`<div class="agent-text" style="color:var(--red)">⚠️ ${esc(friendlyErr(msg.error))}</div>`;}
if(msg.longvideoAssets&&Array.isArray(msg.longvideoAssets)&&msg.longvideoAssets.length){let grid=agentAssetGridHtml(msg.longvideoAssets);if(Array.isArray(msg.failed)&&msg.failed.length){grid+=`<div style="color:var(--amber);font-size:12px;margin-top:4px">${msg.failed.length} 张生成失败</div>`;}
grid+=`<div style="font-size:12px;color:var(--sub);margin-top:6px">请确认素材无误，回复确认后我再提交建长视频草稿。</div>`;html+=grid;}
if(msg.longvideoJob){let jobHtml=(msg.jobName?`已创建长视频任务《${esc(msg.jobName)}》`:"已创建长视频任务");jobHtml+=`<br><button class="lv-go-btn" data-job="${esc(msg.longvideoJob)}">前往长视频工作台 →</button>`;if(Array.isArray(msg.failed)&&msg.failed.length){jobHtml+=`<div class="sub" style="margin-top:6px;color:var(--amber)">有 ${msg.failed.length} 个素材生成失败，可到工作台补充</div>`;}
html+=`<div class="agent-text">${jobHtml}</div>`;}
if(html)bb.insertAdjacentHTML("beforeend",html);if(msg.longvideoAssets)agentBindAssetGrid(bb,msg.longvideoAssets);if(msg.longvideoJob){const btn=bb.querySelector(".lv-go-btn");if(btn)btn.addEventListener("click",()=>agentGotoLongvideo(msg.longvideoJob));}
return;}
const el=agentPendingBubble("恢复任务中…",msg.time);el._msgData=msg;const bubble=el.querySelector(".bubble");const tid=msg.taskId||msg.videoId;if(msg.status==="completed"||msg.videoUrl){agentSettleBubble(el,"");if(msg.media==="image"){const urls=Array.isArray(msg.imageUrls)?msg.imageUrls.filter(Boolean):(msg.videoUrl?[msg.videoUrl]:[]);if(urls.length)renderImageResult(bubble,urls,msg);else bubble.insertAdjacentHTML("beforeend",`<div class="err">该图片结果已失效。</div>`);}else if(msg.videoUrl){renderResult(bubble,msg.videoUrl,msg);}else{bubble.insertAdjacentHTML("beforeend",`<div class="err">该任务没有可用结果。</div>`);}
attachDel(el);return;}
if(msg.status==="failed"){agentSettleBubble(el,"");bubble.insertAdjacentHTML("beforeend",`<div class="err"><span class="ic ic-warn"></span>${esc(friendlyErr(msg.error||"生成失败"))}</div>`);attachDel(el);return;}
if(tid){if(msg.media==="image")startTaskPoll({taskId:tid,msgData:msg,botEl:el,sessId:agentCurrentId});else startPoll({videoId:tid,model:msg.model||currentModel,msgData:msg,botEl:el,sessId:agentCurrentId});}}
function agentBuildStream(){if(agentStreamBuilt)return;const stream=agentEl("agentStream");if(!stream)return;const sess=agentSessions.find(s=>s.id===agentCurrentId);if(!sess)return;agentStreamBuilt=true;const msgs=(sess&&sess.messages)||[];if(!msgs.length){const hello=agentEl("agentHello");if(hello)hello.style.display="";return;}
const hello=agentEl("agentHello");if(hello)hello.style.display="none";stream.querySelectorAll(".msg").forEach(n=>n.remove());msgs.forEach(m=>{try{agentRenderMsg(m);}
catch(err){console.warn("[agentBuildStream] 单条消息渲染失败，已跳过：",err&&err.message);}});scrollLatest(stream);}
function agentSwitchSession(id){if(!id||id===agentCurrentId)return;agentCurrentId=id;agentStreamBuilt=false;const stream=agentEl("agentStream");if(stream)stream.querySelectorAll(".msg").forEach(n=>n.remove());agentBuildStream();agentRecoverActiveRun();agentSaveSessions();agentRenderSessList();}
function agentClearStream(){const stream=agentEl("agentStream");if(stream)stream.querySelectorAll(".msg").forEach(n=>n.remove());const hello=agentEl("agentHello");if(hello)hello.style.display="";}
function agentRenameSession(id,newName){const sess=agentSessions.find(s=>s.id===id);if(!sess)return;const nm=cleanText(newName).replace(/\s+/g," ").slice(0,SESS_NAME_MAX);if(nm&&nm!==sess.name){sess.name=nm;agentSaveSessions();agentRenderSessList();}}
function agentStartRename(sess,item){const nameEl=item.querySelector(".agent-sess-name");if(!nameEl)return;nameEl.contentEditable="true";item.classList.add("editing");nameEl.focus();const r=document.createRange();r.selectNodeContents(nameEl);const s=window.getSelection();s.removeAllRanges();s.addRange(r);const onKey=(e)=>{if(e.key==="Enter"){e.preventDefault();nameEl.blur();}
else if(e.key==="Escape"){nameEl.textContent=sess.name||"未命名";nameEl.blur();}};const onPaste=(e)=>{e.preventDefault();const t=cleanText(e.clipboardData?e.clipboardData.getData("text/plain"):"").replace(/\s+/g," ").slice(0,SESS_NAME_MAX);if(t)document.execCommand("insertText",false,t);};const finish=()=>{nameEl.contentEditable="false";item.classList.remove("editing");nameEl.removeEventListener("blur",finish);nameEl.removeEventListener("keydown",onKey);nameEl.removeEventListener("paste",onPaste);agentRenameSession(sess.id,nameEl.textContent);};nameEl.addEventListener("blur",finish);nameEl.addEventListener("keydown",onKey);nameEl.addEventListener("paste",onPaste);}
function agentRenderSessList(){const list=agentEl("agentSessList");if(!list)return;list.innerHTML="";if(!agentSessions.length){const empty=document.createElement("div");empty.className="agent-empty";empty.textContent="暂无会话\n发第一条消息即可开始";list.appendChild(empty);return;}
const act=s=>{const ms=(s.messages||[]);const last=ms.length?ms[ms.length-1]:null;return Math.max((last&&last.time)?last.time*1000:0,s.createdAt||0);};agentSessions.slice().sort((a,b)=>act(b)-act(a)).forEach(s=>{const item=document.createElement("div");item.className="agent-sess-item"+(s.id===agentCurrentId?" active":"")+(agentSelIds.has(s.id)?" sel":"");const check=agentBatchMode?`<input type="checkbox" class="agent-sess-check"${agentSelIds.has(s.id)?" checked":""} aria-label="选择会话">`:"";const time=`<span class="agent-sess-time">${fmtSessTime(act(s))}</span>`;item.innerHTML=check+`<span class="agent-sess-name" title="${esc(s.name||"未命名")}">${esc(s.name||"未命名")}</span>`+
time+`<button class="sess-dots" title="更多操作" aria-label="更多">⋮</button>`+`<div class="sess-menu">`+`<div class="sess-menu-item" data-act="batch"><span class="ic ic-check"></span>批量管理</div>`+`<div class="sess-menu-item" data-act="rename"><span class="ic ic-pencil"></span>重命名</div>`+`<div class="sess-menu-item" data-act="delete"><span class="ic ic-del"></span>删除</div>`+`</div>`;item.addEventListener("click",(e)=>{if(agentBatchMode){if(e.target.closest(".agent-sess-check"))return;if(e.target.closest(".sess-menu"))return;agentToggleSel(s.id);return;}
if(item.classList.contains("editing"))return;if(e.target.closest(".sess-menu"))return;if(e.target.closest(".sess-dots"))return;agentSwitchSession(s.id);});if(!agentBatchMode){const dots=item.querySelector(".sess-dots");const menu=item.querySelector(".sess-menu");dots.addEventListener("click",(e)=>{e.stopPropagation();const wasOpen=menu.classList.contains("open");closeAllMenus();if(!wasOpen)menu.classList.add("open");});menu.querySelector('[data-act="batch"]').addEventListener("click",(e)=>{e.stopPropagation();closeAllMenus();agentStartBatchWith(s.id);});menu.querySelector('[data-act="rename"]').addEventListener("click",(e)=>{e.stopPropagation();closeAllMenus();agentStartRename(s,item);});menu.querySelector('[data-act="delete"]').addEventListener("click",(e)=>{e.stopPropagation();closeAllMenus();agentDeleteSession(s.id);});item.addEventListener("dblclick",(e)=>{if(e.target.closest(".agent-sess-name")){e.stopPropagation();agentStartRename(s,item);}});}
if(agentBatchMode){const cb=item.querySelector(".agent-sess-check");if(cb)cb.addEventListener("change",()=>agentToggleSel(s.id));}
list.appendChild(item);});}
function agentToggleSel(id){if(agentSelIds.has(id))agentSelIds.delete(id);else agentSelIds.add(id);agentRenderSessList();agentUpdateBatchBar();}
function agentStartBatchWith(id){if(!agentBatchMode){agentBatchMode=true;agentSelIds.clear();agentSelIds.add(id);const side=agentEl("agentSide");const bar=agentEl("agentBatchBar");if(side)side.classList.add("batch");if(bar)bar.classList.add("show");agentRenderSessList();agentUpdateBatchBar();}}
function agentToggleBatch(){agentBatchMode=!agentBatchMode;agentSelIds.clear();const side=agentEl("agentSide");const bar=agentEl("agentBatchBar");if(side)side.classList.toggle("batch",agentBatchMode);if(bar)bar.classList.toggle("show",agentBatchMode);agentRenderSessList();agentUpdateBatchBar();}
function agentUpdateBatchBar(){const bar=agentEl("agentBatchBar");if(!bar)return;const n=agentSelIds.size;const del=bar.querySelector(".abb-del");if(del){del.classList.toggle("cancel",n===0);del.disabled=false;const cnt=del.querySelector(".abb-del-cnt");if(cnt)cnt.textContent=n;}
const allBox=agentEl("agentBatchBox");if(allBox){const total=agentSessions.length;allBox.checked=total>0&&n===total;allBox.indeterminate=n>0&&n<total;}}
async function agentDeleteSelected(){const n=agentSelIds.size;if(n===0)return;if(!confirm(`确定删除选中的 ${n} 个智能会话？相关的图片 / 视频可在资产库中查看。`))return;const ids=[...agentSelIds];agentSessions=agentSessions.filter(s=>!ids.includes(s.id));if(ids.includes(agentCurrentId)){agentCurrentId=agentSessions[0]?agentSessions[0].id:null;agentStreamBuilt=false;agentClearStream();if(agentCurrentId)agentBuildStream();}
agentSelIds.clear();agentBatchMode=false;const side=agentEl("agentSide");const bar=agentEl("agentBatchBar");if(side)side.classList.remove("batch");if(bar)bar.classList.remove("show");agentRenderSessList();agentUpdateBatchBar();agentSaveSessions();}
function agentNewSession(){const id="ag_"+Date.now().toString(36)+"_"+Math.random().toString(36).slice(2,6);const d=new Date(),p=n=>String(n).padStart(2,"0");agentSessions.unshift({id:id,name:"智能会话 "+p(d.getHours())+":"+p(d.getMinutes()),createdAt:Date.now(),messages:[]});agentCurrentId=id;agentStreamBuilt=true;agentClearStream();agentRenderSessList();agentSaveSessions();const t=agentPromptEl();if(t)t.focus();}
function agentDeleteSession(id){const s=agentSessions.find(x=>x.id===id);if(!s)return;if(!confirm(`确定删除智能会话「${s.name||"未命名"}」？相关的图片 / 视频可在资产库中查看。`))return;agentSessions=agentSessions.filter(x=>x.id!==id);if(agentCurrentId===id){agentCurrentId=agentSessions[0]?agentSessions[0].id:null;agentStreamBuilt=false;agentClearStream();agentBuildStream();}
agentRenderSessList();agentSaveSessions();}
let agentPanelFull=false;function agentFabRect(){const fab=agentEl("agentFab");if(!fab)return null;const w=fab.offsetWidth||54,h=fab.offsetHeight||54;const x=parseFloat(fab.style.left),y=parseFloat(fab.style.top);if(isFinite(x)&&isFinite(y))return{left:x,top:y,width:w,height:h,right:x+w,bottom:y+h};const r=fab.getBoundingClientRect();return{left:r.left,top:r.top,width:r.width||w,height:r.height||h,right:r.right||r.left+w,bottom:r.bottom||r.top+h};}
function agentPositionPanel(){const p=agentEl("agentPanel"),fab=agentEl("agentFab");if(!p||!fab)return;const VW=window.innerWidth,VH=window.innerHeight,G=24,GAPF=12;if(agentPanelFull){p.style.left="0px";p.style.top="0px";p.style.width=VW+"px";p.style.height=VH+"px";p.style.transformOrigin="50% 50%";return;}
const W=Math.min(380,Math.max(240,VW-2*G));let H=Math.min(520,Math.max(240,Math.round(VH*0.68)),VH-2*G);const f=agentFabRect();if(!f)return;const side=fab.dataset.side||"right";let left;if(side==="left")left=Math.round(f.right+GAPF);else if(side==="right")left=Math.round(f.left-GAPF-W);else left=Math.round(f.left+f.width/2-W/2);left=Math.min(Math.max(G,left),Math.max(G,VW-W-G));const overlapX=!(left>=f.right+1||left+W<=f.left-1);const gapBelow=VH-(f.bottom+GAPF)-G;const gapAbove=(f.top-GAPF)-G;const openBelow=gapBelow>=gapAbove;if(overlapX){const maxGap=Math.max(gapBelow,gapAbove);if(maxGap<H)H=Math.max(160,Math.min(H,maxGap));}
let top=openBelow?(f.bottom+GAPF):(f.top-GAPF-H);top=Math.min(Math.max(G,top),Math.max(G,VH-H-G));p.style.left=left+"px";p.style.top=Math.round(top)+"px";p.style.width=Math.round(W)+"px";p.style.height=Math.round(H)+"px";const ox=Math.min(100,Math.max(0,Math.round(((f.left+f.width/2)-left)/W*100)));p.style.transformOrigin=ox+"% "+(openBelow?"0%":"100%");}
function agentSetFull(on,opts){const o=opts||{};const p=agentEl("agentPanel");if(!p)return;agentPanelFull=!!on;p.classList.toggle("is-full",agentPanelFull);const btn=agentEl("agentFull");if(btn){const ic=btn.querySelector(".ic"),lbl=btn.querySelector(".lbl");if(ic)ic.className=agentPanelFull?"ic ic-min":"ic ic-max";if(lbl)lbl.textContent=agentPanelFull?"还原":"历史";}
if(agentPanelFull)agentRenderSessList();agentPositionPanel();if(!o.skipAnchor)agentFollowWhileTransition(p,agentEl("agentStream"),340);agentSavePanelState();}
function agentSavePanelState(){try{const p=agentEl("agentPanel");localStorage.setItem(AGENT_PANEL_KEY,JSON.stringify({open:!!(p&&p.classList.contains("show")),full:!!agentPanelFull}));}catch(_){}}
function agentOpenPanel(show){const p=agentEl("agentPanel");if(!p)return;const next=(typeof show==="boolean")?show:!p.classList.contains("show");const fab=agentEl("agentFab");if(fab)fab.classList.toggle("is-open",next);if(next){agentSetFull(false,{skipAnchor:true});agentPositionPanel();agentBuildStream();const stream=agentEl("agentStream");const hello=agentEl("agentHello");if(hello&&stream&&stream.querySelectorAll(".msg").length===0)hello.style.display="";scrollLatest(stream,{sync:true});p.classList.add("show");scrollLatest(stream,{sync:true});agentAnchorWhenSettled(p,stream);setTimeout(()=>{const t=agentPromptEl();if(t)t.focus({preventScroll:true});},80);}else{scrollAnchorCancel(agentEl("agentStream"));p.classList.remove("show");agentSetFull(false,{skipAnchor:true});agentAnchorWhenSettled(p,agentEl("agentStream"));}
agentSavePanelState();}
function agentAddMsg(role,innerHtml,time){const stream=agentEl("agentStream");if(!stream)return null;const hello=agentEl("agentHello");if(hello)hello.style.display="none";const t=(time!=null)?fmtTime(time):fmtTime(Date.now()/1000);const el=document.createElement("div");el.className="msg "+(role==="user"?"user":"bot");el.innerHTML=(role==="user")?`<div class="msg-col"><div class="bubble"><div class="agent-text">${esc(innerHtml).replace(/\n/g,"<br>")}</div></div><div class="msg-foot"><span class="meta"><span class="t">${t}</span></span></div></div>`:`<div class="av">AI</div><div class="msg-col"><div class="bubble">${innerHtml}</div><div class="msg-foot"><span class="meta"><span class="t">${t}</span></span></div></div>`;stream.appendChild(el);stream.scrollTop=stream.scrollHeight;return el;}
function agentRenderBubbleAssets(el,assets){if(!el||!assets||!assets.length)return;const bubble=el.querySelector(".bubble");if(!bubble)return;let html='<div class="agent-att">';assets.filter(a=>a.kind==="image").forEach(a=>{html+=`<img src="${esc(thumbUrl(a.url||"",128))}" alt="" title="${esc(a.name||"素材")}">`;});assets.filter(a=>a.kind!=="image").forEach(a=>{html+=`<span class="agent-att-o">${a.kind==="audio"?"🎵":"🎬"} ${esc(a.name||(a.kind==="audio"?"音频":"视频"))}</span>`;});html+='</div>';bubble.insertAdjacentHTML("beforeend",html);}
function agentPendingBubble(text,time){return agentAddMsg("bot",`<div class="st"><span class="d" id="dot"></span><span id="stxt">${esc(text)}</span></div>`+`<div class="track"><i></i></div><div class="sub" id="sub"></div>`,time);}
function agentGotoLongvideo(jobId){if(!jobId)return;const el=document.getElementById("media");if(el){el.value="longvideo";el.dispatchEvent(new Event("change",{bubbles:true}));}
const open=(typeof window.lvOpenJob==="function")?window.lvOpenJob:null;const ok=open?!!open(jobId):false;if(!ok)toast("长视频工作台还没准备好，请从底部媒体菜单进入（任务已保存，不会丢）");agentOpenPanel(false);}
function agentStreamShowTool(st,text){if(!st||!st.toolEl)return;st.toolTxt.textContent=text||"正在调用工具执行任务…";st.toolEl.hidden=false;st.toolShown=true;}
function agentStreamToolManifest(st,ev){if(!st||!st.gridEl)return;let items=[];if(ev&&Array.isArray(ev.items)){items=ev.items.map((it,i)=>({index:(it.index!=null)?it.index:i,label:String(it.label||"").slice(0,40),kind:it.kind||"prop",url:it.url||"",state:it.url?"done":"pending"}));}else if(ev&&Array.isArray(ev.labels)){items=ev.labels.map((l,i)=>({index:i,label:String(l||"").slice(0,40),kind:"prop",url:"",state:"pending"}));}
st.gridItems=items;st.gridEl.hidden=!items.length;if(items.length&&!st.toolShown&&st.toolEl){st.toolEl.hidden=false;st.toolShown=true;}
agentStreamToolGridRender(st);}
function agentShowToolProgress(st,ev){if(!st||!ev||!st.toolEl)return;if(!st.toolShown){st.toolEl.hidden=false;st.toolShown=true;}
if(st.toolTxt&&ev.text)st.toolTxt.textContent=ev.text;if(st.toolBar&&ev.total){st.toolBar.style.width=Math.max(6,Math.round((ev.done||0)/ev.total*100))+"%";}
if(ev.total&&st.gridItems&&st.gridItems.length){const n=Math.min(Math.max(ev.done||0,0),st.gridItems.length);st.gridItems.forEach((it,i)=>{if(i<n)it.state=it.url?"done":"pending";else if(i===n)it.state="doing";});if(!st.lvStart[n])st.lvStart[n]=Date.now();agentLvTimerEnsure(st);}
const doneItems=Array.isArray(ev.items)?ev.items:(ev.item?[ev.item]:[]);doneItems.forEach(it=>{if(!it)return;const idx=(it.index!=null)?it.index:(ev.done!=null?ev.done-1:0);const g=st.gridItems.find(x=>x.index===idx);if(g){g.url=it.url||g.url;if(g.url){g.state="done";delete st.lvStart[idx];}}});agentStreamToolGridRender(st);agentLvTimerEnsure(st);const se=agentEl("agentStream");if(se&&(se.scrollHeight-se.scrollTop-se.clientHeight<160))se.scrollTop=se.scrollHeight;}
function agentLvWaitText(st,idx){const t0=st.lvStart&&st.lvStart[idx];if(!t0)return"";const s=Math.max(0,Math.floor((Date.now()-t0)/1000));const m=Math.floor(s/60);return(m>0?m+":":"")+String(s%60).padStart(m>0?2:1,"0")+" 未出图";}
function agentLvTimerEnsure(st){if(!st||!st.gridEl)return;if(st.lvTimer)return;st.lvTimer=setInterval(()=>{if(!st.gridEl||!st.lvStart)return;Object.keys(st.lvStart).forEach(idx=>{const el=st.gridEl.querySelector('.agent-lv-card[data-index="'+idx+'"] .agent-lv-wait');if(el)el.textContent=agentLvWaitText(st,idx);});},1000);}
function agentLvTimerClear(st){if(st&&st.lvTimer){clearInterval(st.lvTimer);st.lvTimer=0;}}
function agentStreamToolGridRender(st){if(!st||!st.gridEl)return;st.gridEl.innerHTML=st.gridItems.map(it=>{const title=esc(it.label||"");if(it.state==="done"&&it.url){return`<div class="agent-lv-card done" data-index="${it.index}" title="点击放大查看">`+`<img src="${esc(thumbUrl(it.url,320))}" alt="${title}" loading="lazy" decoding="async"/>`+`<div class="agent-lv-label">${title}</div></div>`;}
const cls="agent-lv-card "+(it.state==="doing"?"doing":"pending");return`<div class="${cls}" data-index="${it.index}">`+`<div class="agent-lv-placeholder"><span class="ic ic-image"></span><span class="agent-lv-label">${title}</span></div>`+`<span class="agent-lv-wait">${esc(agentLvWaitText(st,it.index))}</span>`+`</div>`;}).join("");const stream=agentEl("agentStream");st.gridEl.querySelectorAll(".agent-lv-card.done").forEach(card=>{card.addEventListener("click",()=>{const doneList=st.gridItems.filter(x=>x.url);const idx=doneList.findIndex(x=>x.index===parseInt(card.dataset.index,10));const it=st.gridItems.find(x=>x.index===parseInt(card.dataset.index,10));if(typeof openLightbox==="function"&&doneList.length){openLightbox(doneList.map(x=>x.url),Math.max(0,idx),it&&it.label);}});});if(stream&&(stream.scrollHeight-stream.scrollTop-stream.clientHeight<160))stream.scrollTop=stream.scrollHeight;}
function agentInline(s){return s.replace(/\*\*([^*]+)\*\*/g,"<strong>$1</strong>").replace(/`([^`]+)`/g,"<code>$1</code>");}
function agentCells(line){return line.trim().replace(/^\|/,"").replace(/\|$/,"").split("|").map(function(s){return s.trim();});}
function agentTableHtml(head,rows){var h='<div class="agent-tw"><table class="agent-tb"><thead><tr>';for(var i=0;i<head.length;i++)h+="<th>"+agentInline(head[i])+"</th>";h+="</tr></thead><tbody>";for(var r=0;r<rows.length;r++){h+="<tr>";for(var k=0;k<head.length;k++)h+="<td>"+agentInline(rows[r][k]||"")+"</td>";h+="</tr>";}
return h+"</tbody></table></div>";}
